total = 0
banyak = 0
terbesar = 0
boks = int(input())
while boks != 0:
    if boks < 0:
        print("Jumlah tidak valid, dilewati")
    else:
        banyak += 1
        total += boks
        if boks > terbesar:
            terbesar = boks
    boks = int(input())
if banyak == 0:
    print("Tidak ada pesanan")
else:
    print("Jumlah pesanan:", banyak)
    print("Total boks:", total)
    print("Rata-rata:", f"{total / banyak:.2f}")
    print("Terbesar:", terbesar)

